/* Independent per-line run count for a token span (#728 oracle). */
static uint32_t ref_line_runs(const char*t,uint32_t a,uint32_t e){uint32_t n=0;while(a<e){uint32_t q=a;while(q<e&&t[q]!='\n')q++;if(q>a)n++;a=q<e?q+1:q;}return n;}
static uint64_t ref_runs_total(const SeditLexer*l,const char*t){uint64_t n=0;for(size_t i=0;i<l->token_count;i++)n+=ref_line_runs(t,l->tokens[i].start,l->tokens[i].end);return n;}
static int has(const SeditLexer*l,int k,const char*s,const char*src){for(size_t i=0;i<l->token_count;i++)if(l->tokens[i].kind==k&&l->tokens[i].end-l->tokens[i].start==strlen(s)&&!memcmp(src+l->tokens[i].start,s,strlen(s)))return 1;return 0;}
static int lex_equal(const SeditLexer*a,const SeditLexer*b){return a->token_count==b->token_count&&a->pair_count==b->pair_count&&!memcmp(a->tokens,b->tokens,a->token_count*sizeof(*a->tokens))&&!memcmp(a->pairs,b->pairs,a->pair_count*sizeof(*a->pairs));}
typedef struct { SeditToken t[4096]; size_t nt; SeditPair p[4096]; size_t np; } Ref;
static int ref_word(const char*s,size_t n,int*kind){static const char*ty[]={"auto","bool","char","const","double","enum","extern","float","inline","int","long","register","restrict","short","signed","static","struct","typedef","union","unsigned","void","volatile","_Atomic","_Bool","_Complex","_Imaginary",0};static const char*kw[]={"break","case","continue","default","do","else","for","goto","if","return","sizeof","switch","while","_Alignas","_Alignof","_Generic","_Noreturn","_Static_assert","_Thread_local",0};for(int i=0;ty[i];i++)if(strlen(ty[i])==n&&!memcmp(s,ty[i],n)){*kind=SEDIT_T_TYPE;return 1;}for(int i=0;kw[i];i++)if(strlen(kw[i])==n&&!memcmp(s,kw[i],n)){*kind=SEDIT_T_KEYWORD;return 1;}return 0;}
static void rt(Ref*r,size_t a,size_t b,int k){if(b>a&&r->nt<4096)r->t[r->nt++]=(SeditToken){(uint32_t)a,(uint32_t)b,(uint8_t)k};}
static int ropen(char c){return c=='('?')':c=='['?']':c=='{'?'}':0;}
static void ref_scan(const char*s,size_t n,Ref*r){memset(r,0,sizeof* r);struct{size_t at;char close;}st[1024];size_t ns=0;int bol=1;for(size_t i=0;i<n;){unsigned char c=s[i];if(c=='\n'){bol=1;i++;continue;}if(c==' '||c=='\t'||c=='\r'){i++;continue;}if(c=='#'&&bol){size_t a=i++;int esc=0;while(i<n){if(s[i]=='\\'){esc=!esc;i++;continue;}if(s[i]=='\n'&&!esc)break;esc=0;i++;}rt(r,a,i,SEDIT_T_PREPROCESSOR);continue;}bol=0;if(c=='/'&&i+1<n&&s[i+1]=='*'){size_t a=i;i+=2;while(i+1<n&&(s[i]!='*'||s[i+1]!='/'))i++;if(i+1<n)i+=2;rt(r,a,i,SEDIT_T_COMMENT);continue;}if(c=='/'&&i+1<n&&s[i+1]=='/'){size_t a=i;i+=2;while(i<n&&s[i]!='\n')i++;rt(r,a,i,SEDIT_T_COMMENT);continue;}if(c=='"'||c=='\''){char q=(char)c;size_t a=i++;int esc=0;while(i<n&&s[i]!='\n'){char z=s[i++];if(esc){esc=0;continue;}if(z=='\\'){esc=1;continue;}if(z==q)break;}rt(r,a,i,q=='"'?SEDIT_T_STRING:SEDIT_T_CHAR);continue;}if(isalpha(c)||c=='_'||c>=0x80){size_t a=i++;while(i<n&&((unsigned char)s[i]>=0x80||isalnum((unsigned char)s[i])||s[i]=='_'))i++;int k;if(ref_word(s+a,i-a,&k))rt(r,a,i,k);continue;}if(isdigit(c)||(c=='.'&&i+1<n&&isdigit((unsigned char)s[i+1]))){size_t a=i++;int exp=0;while(i<n){char z=s[i];if(isalnum((unsigned char)z)||z=='.'){exp=z=='e'||z=='E'||z=='p'||z=='P';i++;continue;}if((z=='+'||z=='-')&&exp){exp=0;i++;continue;}break;}rt(r,a,i,SEDIT_T_NUMBER);continue;}int close=ropen((char)c);if(close){if(ns<1024){st[ns].at=i;st[ns].close=(char)close;ns++;}rt(r,i,i+1,SEDIT_T_PUNCT);i++;continue;}if(c==')'||c==']'||c=='}'){if(ns&&st[ns-1].close==(char)c){size_t a=st[--ns].at;r->p[r->np++]=(SeditPair){(uint32_t)a,(uint32_t)i,0};r->p[r->np++]=(SeditPair){(uint32_t)i,(uint32_t)a,0};}else r->p[r->np++]=(SeditPair){(uint32_t)i,(uint32_t)i,1};rt(r,i,i+1,SEDIT_T_PUNCT);i++;continue;}i++;}while(ns){size_t a=st[--ns].at;r->p[r->np++]=(SeditPair){(uint32_t)a,(uint32_t)a,1};}}
/* Deliberately defective scanner: it has no BLOCK_COMMENT state, so braces
 * and words inside a block comment are treated as live source. */
static void broken_scan_no_block_comments(const char*s,size_t n,Ref*r){memset(r,0,sizeof* r);struct{size_t at;char close;}st[1024];size_t ns=0;for(size_t i=0;i<n;){unsigned char c=s[i];if(c=='"'||c=='\''){char q=(char)c;size_t a=i++;int esc=0;while(i<n&&s[i]!='\n'){char z=s[i++];if(esc){esc=0;continue;}if(z=='\\'){esc=1;continue;}if(z==q)break;}rt(r,a,i,q=='"'?SEDIT_T_STRING:SEDIT_T_CHAR);continue;}if(isalpha(c)||c=='_'||c>=0x80){size_t a=i++;while(i<n&&((unsigned char)s[i]>=0x80||isalnum((unsigned char)s[i])||s[i]=='_'))i++;int k;if(ref_word(s+a,i-a,&k))rt(r,a,i,k);continue;}int close=ropen((char)c);if(close){st[ns].at=i;st[ns].close=(char)close;ns++;rt(r,i,i+1,SEDIT_T_PUNCT);i++;continue;}if(c==')'||c==']'||c=='}'){if(ns&&st[ns-1].close==(char)c){size_t a=st[--ns].at;r->p[r->np++]=(SeditPair){(uint32_t)a,(uint32_t)i,0};r->p[r->np++]=(SeditPair){(uint32_t)i,(uint32_t)a,0};}else r->p[r->np++]=(SeditPair){(uint32_t)i,(uint32_t)i,1};rt(r,i,i+1,SEDIT_T_PUNCT);i++;continue;}i++;}while(ns){size_t a=st[--ns].at;r->p[r->np++]=(SeditPair){(uint32_t)a,(uint32_t)a,1};}}
static int lex_ref_equal(const SeditLexer*l,const Ref*r){return l->token_count==r->nt&&l->pair_count==r->np&&!memcmp(l->tokens,r->t,r->nt*sizeof*r->t)&&!memcmp(l->pairs,r->p,r->np*sizeof*r->p);}
/* Injected turn clock (#729): counts calls, steps a fixed amount per call. */
typedef struct { long long t, step; int calls; } FakeClock;
static long long fake_now(void*p){FakeClock*c=(FakeClock*)p;c->calls++;long long v=c->t;c->t+=c->step;return v;}
static int check_all_splits(const char*s,size_t n,const Ref*r){for(size_t cut=0;cut<=n;cut++){SeditLexer q;sedit_lex_init(&q);int ok=sedit_lex_feed(&q,s,cut)&&sedit_lex_feed(&q,s+cut,n-cut)&&sedit_lex_finish(&q)&&lex_ref_equal(&q,r);sedit_lex_free(&q);if(!ok)return 0;}return 1;}
