static int fault,eintr_once,unlinks,stat_calls,hash_calls;
static int t_open(const char*p,int f,mode_t m){if(fault==1&&(f&O_WRONLY)){errno=ENOSPC;return-1;}return open(p,f,m);}
static ssize_t t_write(int fd,const void*b,size_t n){if(fault==2||fault==10){errno=ENOSPC;return-1;}if(fault==3&&eintr_once++==0){errno=EINTR;return-1;}if(fault==4&&n>1)n=1;return write(fd,b,n);}
static int t_chmod(int fd,mode_t m){if(fault==5){errno=EPERM;return-1;}return fchmod(fd,m);}
static int t_fsync(int fd){if(fault==6){errno=ENOSPC;return-1;}return fsync(fd);}
static int t_close(int fd){int r=close(fd);if(fault==7){errno=EIO;return-1;}return r;}
static int t_rename(const char*a,const char*b){if(fault==8){errno=EACCES;return-1;}return rename(a,b);}
static int t_unlink(const char*p){unlinks++;if(fault==10){errno=EACCES;return-1;}return unlink(p);}
static int t_stat(const char*p,struct stat*s){stat_calls++;if(fault==11&&stat_calls>=2){errno=EIO;return-1;}return stat(p,s);}
static int t_sha(const char*p,char h[65]){hash_calls++;if(fault==9||(fault==12&&hash_calls>=2)){errno=EIO;return-1;}return sha256_path(p,h);}
static void set_fault(int f){SeditIOOps o={0};fault=f;eintr_once=0;unlinks=0;stat_calls=hash_calls=0;o.stat_fn=t_stat;o.open_fn=t_open;o.write_fn=t_write;o.fchmod_fn=t_chmod;o.fsync_fn=t_fsync;o.close_fn=t_close;o.rename_fn=t_rename;o.unlink_fn=t_unlink;o.sha256_path_fn=t_sha;sedit_document_test_io(&o);}
static int exact_file(const char*p,const char*s,size_t n){char b[64];FILE*f=fopen(p,"rb");if(!f)return 0;size_t z=fread(b,1,sizeof b,f);fclose(f);return z==n&&!memcmp(b,s,n);}
static int temp_count(const char*dir){DIR*d=opendir(dir);if(!d)return-1;int n=0;struct dirent*e;while((e=readdir(d)))if(strstr(e->d_name,".sedit.")&&strstr(e->d_name,".tmp"))n++;closedir(d);return n;}
